declare plan jsonb := '{"classes":[{"id":"03bf9915-c730-4442-bff5-b79fb2eb0c92","name":"Singapore National Sailing Championships 2023 (Optimist Gold)","slug":"snsc-gold-sep-23-2023-09-02","venue":null,"status":"published","event_id":"9e2e126d-e354-4655-ad29-5ff921263729","parent_name":"Singapore National Sailing Championships 2023","parent_slug":"national-sailing-championships-2023","parent_venue":"National Sailing Centre, Singapore","target_venue":"National Sailing Centre, Singapore"},{"id":"0d499bb6-fc25-4cb3-ba0d-4fb34c36ba84","name":"RSYC Optimist Knockout Championship 2025 (Silver)","slug":"rsyc-2025-silver","venue":null,"status":"published","event_id":"434d7b39-924f-49d5-a5e6-519c55208b75","parent_name":"RSYC Optimist Silver Fleet Knockout Championship 2025","parent_slug":"rsyc-optimist-silver-fleet-knockout-championship-2025","parent_venue":"Republic of Singapore Yacht Club","target_venue":"Republic of Singapore Yacht Club"},{"id":"1fd2c1a6-e60f-41ff-872e-6ba37e789af2","name":"2025 Northeast Monsoon Grand Prix Combined Series \u2014 Techno 293","slug":"ne-monsoon-grand-prix-2025-combined-techno-293","venue":null,"status":"published","event_id":"e68ebd91-668c-439f-8667-77587a7c7929","parent_name":"2025 Northeast Monsoon Grand Prix Combined Series","parent_slug":"ne-monsoon-grand-prix-2025-combined","parent_venue":"Changi Beach Park CP 1 / Tanah Merah, Singapore","target_venue":"Changi Beach Park CP 1 / Tanah Merah, Singapore"},{"id":"23c927bf-3f8d-47bd-a22d-7b2e4e642f26","name":"2025 Northeast Monsoon Grand Prix Series 2 \u2014 Windfoil","slug":"ne-monsoon-grand-prix-2025-series-2-windfoil","venue":null,"status":"published","event_id":"01aa0332-1475-4817-ba9f-cd5a478d7f85","parent_name":"2025 Northeast Monsoon Grand Prix Series 2","parent_slug":"ne-monsoon-grand-prix-2025-series-2","parent_venue":"Changi Beach Park CP 1 / Tanah Merah, Singapore","target_venue":"Changi Beach Park CP 1 / Tanah Merah, Singapore"},{"id":"2a1e17a4-d093-42ba-ae46-a041f2a5c49f","name