_name":"RSYC Optimist Gold Knockout Championship 2026","parent_slug":"rsyc-optimist-gold-fleet-knockout-championship-2026","parent_venue":"Republic of Singapore Yacht Club","target_venue":"Republic of Singapore Yacht Club"},{"id":"a4bea356-ba27-4136-a140-310b4a4853a7","name":"Selection Trials (Aug 26)","slug":"selection-trials-aug-26-2026-08-22","venue":null,"status":"published","event_id":"0e17d6c8-1e64-49fe-8667-b213e44bdc59","parent_name":"2026 SSF Selection Trials","parent_slug":"ssf-selection-trials-2026","parent_venue":"National Sailing Centre, East Coast","target_venue":"National Sailing Centre, East Coast"},{"id":"abe1094f-c73d-4c42-93af-171d9abc41a6","name":"2025 Northeast Monsoon Grand Prix Combined Series \u2014 Windfoil","slug":"ne-monsoon-grand-prix-2025-combined-windfoil","venue":null,"status":"published","event_id":"e68ebd91-668c-439f-8667-77587a7c7929","parent_name":"2025 Northeast Monsoon Grand Prix Combined Series","parent_slug":"ne-monsoon-grand-prix-2025-combined","parent_venue":"Changi Beach Park CP 1 / Tanah Merah, Singapore","target_venue":"Changi Beach Park CP 1 / Tanah Merah, Singapore"},{"id":"c028dc96-85d6-4335-b407-817f1b4eec09","name":"Cincapura 2026 (ILCA 4)","slug":"cincapura-2026-ilca4","venue":null,"status":"published","event_id":"a73fee2e-e7c0-401e-9e22-b32badbf88f0","parent_name":"Cincapura Regatta 2026","parent_slug":"cincapura-regatta-2026","parent_venue":"National Sailing Centre, Singapore","target_venue":"National Sailing Centre, Singapore"},{"id":"c5f3cf38-3ac6-4140-84d5-3ecff7ca05ea","name":"2025 Northeast Monsoon Grand Prix Series 2 \u2014 Wingfoil","slug":"ne-monsoon-grand-prix-2025-series-2-wingfoil","venue":null,"status":"published","event_id":"01aa0332-1475-4817-ba9f-cd5a478d7f85","parent_name":"2025 Northeast Monsoon Grand Prix Series 2","parent_slug":"ne-monsoon-grand-prix-2025-series-2","parent_venue":"Changi Beach Park CP 1 / Tanah Merah, Singapore","target_venue":"Changi Beach Park CP 1 / Tanah Merah, Singapore"},{"id":"d09dad16-54f6-4c8a-954b-6e7c76da05c0","name":"2025 Northeast Monsoon Grand Prix Series 3 GPS Speed Challenge \u2014 Wingfoil","slug":"ne-monsoon-grand-prix-2025-gps-speed-challenge-wingfoil","venue":null,"status":"published","event_id":"c72d9101-af79-4e66-940b-906a55cbeac6","parent_name":"2025 Northeast Monsoon Grand Prix Series 3 GPS Speed Challenge","parent_slug":"ne-monsoon-grand-prix-2025-gps-speed-challenge","parent_venue":"Singapore waters","target_venue":"Singapore waters"},{"id":"d59895ec-ae12-48f6-897c-376e7f58c742","name":"Raffles Marina Optimist Regatta 2023 (Optimist Silver)","slug":"rm-silver-may-23-2023-05-27","venue":null,"status":"published","event_id":"2a9e9a98-fe5c-5f7f-b100-679d8d6d32a4","parent_name":"Raffles Marina Optimist Regatta 2023","parent_slug":"raffles-marina-optimist-regatta-2023","parent_venue":null,"target_venue":"Raffles Marina"},{"id":"dea8db5f-6e14-473b-b230-821a640d27ee","name":"RSYC Optimist Knockout Championship 2025 (Gold)","slug":"rsyc-2025-gold","venue":null,"status":"published","event_id":"c306d7ab-42bb-4681-84e2-eaf80ff88e4f","parent_name":"RSYC Optimist Gold Knockout Championship 2025","parent_slug":"rsyc-optimist-knockout-championship-2025","parent_venue":"Republic of Singapore Yacht Club","target_venue":"Republic of Singapore Yacht Club"},{"id":"df6f3e1b-577e-4aa5-92a5-e0facee5d607","name":"Temasek ILCA (Jun 26)","slug":"temasek-ilca-jun-26-2026-06-20","venue":null,"status":"published","event_id":"f4d02a27-d032-4df4-af5b-a96e20222305","parent_name":"Temasek Regatta 2026","parent_slug":"temasek-regatta-2026","parent_venue":"National Sailing Centre, 1500 East Coast Parkway","target_venue":"National Sailing Centre, 1500 East Coast Parkway"},{"id":"fc04d3e2-9a62-406b-90c9-b7a2ccc852dc","name":"22nd SAFYC Regatta (Silver)","slug":"22nd-safyc-regatta-silver-2026-03-28","venue":null,"status":"published","event_id":"e2e93deb-de9f-4b2a-bf6e-5b8fe372bc4f","parent_name":"22nd SAFYC Regatta 2026","parent_slug":"22nd-safyc-regatta-2026","parent_venue":"NSRCC Seasports Centre, 11 Changi Coast Walk, Singapore 499740","target_venue":"NSRCC Seasports Centre, 11 Changi Coast Walk, Singapore 499740"}],"parents":[{"id":"f4aebdee-95a9-5182-9d0d-82b45c61c64c","name":"Singapore Youth Sailing Championships 2023","slug":"singapore-youth-sailing-championships-2023","venue":null,"classes":["Optimist Gold","Optimist Silver"],"nor_url":null,"end_date":"2023-03-14","organizer":null,"created_at":"2026-10-17T08:56:32.314069+00:00","start_date":"2023-03-11","updated_at":"2026-10-17T09:26:41.168+00:00","key_deadlines":null,"scoring_rules":null,"registration_url":null,"schedule_summary":null,"counts_for_ranking":true,"is_selection_trial":false},{"id":"2a9e9a98-fe5c-5f7f-b100-679d8d6d32a4","name":"Raffles Marina Optimist Regatta 2023","slug":"raffles-marina-optimist-regatta-2023","venue":null,"classes":["Optimist Gold","Optimist Silver"],"nor_url":null,"end_date":"2023-05-28","organizer":null,"created_at":"2026-10-17T08:57:38.581107+00:00","start_date":"2023-05-27","updated_at":"2026-10-17T08:57:38.581107+00:00","key_deadlines":null,"scoring_rules":null,"registration_url":null,"schedule_summary":null,"counts_for_ranking":true,"is_selection_trial":false}]}'::jsonb; item jsonb; par regatta_events%rowtype; sheet regattas%rowtype; target text; ids uuid[];
result_hash text; race_hash text; participant_hash text; replay boolean;
begin
select array_agg((x->>'id')::uuid) into ids from jsonb_array_elements(plan->'classes') x;
perform 1 from regatta_events where id in(select (x->>'event_id')::uuid from jsonb_array_elements(plan->'classes') x) order by id for update;
perform 1 from regattas where id=any(ids) order by id for update;
select exists(select 1 from admin_change_log where source='regatta-venues-class-results-review-2026-10-17' and action='regattas.repair_blank_venues') into replay;
if not replay then
 for item in select value from jsonb_array_elements(plan->'parents') loop
  select * into strict par from regatta_events where id=(item->>'id')::uuid;
  if par.slug<>item->>'slug' or par.venue is distinct from item->>'venue' then raise exception 'Parent venue preflight changed: %',item->>'name'; end if;
 end loop;
 for item in select value from jsonb_array_elements(plan->'classes') loop
  select * into strict sheet from regattas where id=(item->>'id')::uuid;
  select * into strict par from regatta_events where id=sheet.event_id;
  if sheet.event_id<>(item->>'event_id')::uuid or sheet.status<>item->>'status' or sheet.venue is distinct from item->>'venue' or nullif(btrim(sheet.venue),'') is not null or par.venue is distinct from item->>'parent_venue' then raise exception 'Class/parent venue preflight changed: %',item->>'name'; end if;
 end loop;
 select md5(jsonb_agg(to_jsonb(r) order by r.id)::text) into result_hash from regatta_results r where regatta_id=any(ids);
 select md5(jsonb_agg(to_jsonb(rr) order by rr.id)::text) into race_hash from regatta_race_results rr join regatta_results r on r.id=rr.regatta_result_id where r.regatta_id=any(ids);
 select md5(jsonb_agg(to_jsonb(pp) order by pp.id)::text) into participant_hash from regatta_result_participants pp join regatta_results r on r.id=pp.regatta_result_id where r.regatta_id=any(ids);
 insert into admin_change_log(action,entity_type,summary,details,source) values('regattas.repair_blank_venues','regatta_event','Saved two user-confirmed event venues and populated 27 blank class venues from their reviewed parent records.',jsonb_build_object('beforeParents',(select jsonb_agg(to_jsonb(e)) from regatta_events e where id in(select (x->>'id')::uuid from jsonb_array_elements(plan->'parents') x)),'beforeClasses',(select jsonb_agg(to_jsonb(g)) from regattas g where id=any(ids)),'plan',plan,'resultHash',result_hash,'raceHash',race_hash,'participantHash',participant_hash,'authorization','User supplied National Sailing Centre for SYSC 2023 and Raffles Marina for RMOR 2023; requested empty class venues follow parent venues.'),'regatta-venues-class-results-review-2026-10-17');
 for item in select value from jsonb_array_elements(plan->'parents') loop
  target=case item->>'slug' when 'singapore-youth-sailing-championships-2023' then 'National Sailing Centre' when 'raffles-marina-optimist-regatta-2023' then 'Raffles Marina' end;
  if target is null then raise exception 'Unreviewed parent in venue plan'; end if;
  update regatta_events set venue=target,updated_at=now() where id=(item->>'id')::uuid;
 end loop;
 for item in select value from jsonb_array_elements(plan->'classes') loop
  select venue into strict target from regatta_events where id=(item->>'event_id')::uuid;
  if target is distinct from item->>'target_venue' or nullif(btrim(target),'') is null then raise exception 'Parent does not match reviewed target venue'; end if;
  update regattas set venue=target,updated_at=now() where id=(item->>'id')::uuid and nullif(btrim(venue),'') is null;
 end loop;
 if result_hash is distinct from (select md5(jsonb_agg(to_jsonb(r) order by r.id)::text) from regatta_results r where regatta_id=any(ids)) or race_hash is distinct from (select md5(jsonb_agg(to_jsonb(rr) order by rr.id)::text) from regatta_race_results rr join regatta_results r on r.id=rr.regatta_result_id where r.regatta_id=any(ids)) or participant_hash is distinct from (select md5(jsonb_agg(to_jsonb(pp) order by pp.id)::text) from regatta_result_participants pp join regatta_results r on r.id=pp.regatta_result_id where r.regatta_id=any(ids)) then raise exception 'Venue metadata repair changed a result, race or participant'; end if;
end if;
for item in select value from jsonb_array_elements(plan->'classes') loop
 if not exists(select 1 from regattas g join regatta_events e on e.id=g.event_id where g.id=(item->>'id')::uuid and g.venue=item->>'target_venue' and e.venue=g.venue and g.status=item->>'status') then raise exception 'Venue repair verification failed'; end if;
end loop;
if jsonb_array_length(plan->'classes')<>27 or jsonb_array_length(plan->'parents')<>2 then raise exception 'Reviewed venue inventory differs'; end if;
end $venues$;
commit;
